#!/usr/bin/env python3
"""Materialize finite ACT data for the typed matcher, without executing prose."""
from pathlib import Path
import argparse,hashlib,json,unicodedata
ROOT=Path(__file__).resolve().parents[1]
DATA=ROOT/'docs/architecture/activity-vocabulary-20261028.json'
OUT=ROOT/'packages/finance-core/src/catalog/generated/activity-v1.ts'
def build():
 raw=DATA.read_bytes();d=json.loads(raw)
 if len(d['entries'])!=194 or sum(len(e['forms']) for e in d['entries'])!=4282:raise ValueError('ACT coverage changed')
 rows=[{'id':e['id'],'domain':e['domain'],'key':e['category']['key'],'mode':e['category']['mode'],'forms':[f['text'] for f in e['forms']]} for e in d['entries']]
 extras={chr(i):chr(i).casefold() for i in range(0x110000) if chr(i).lower()==chr(i) and chr(i).casefold()!=chr(i)}
 targets=[{'key':t['semantic_key'],'path':t['preferred_path'].split(' / '),'labels':t['candidate_labels']} for t in d['category_name_candidates']]
 values={'activityDefinitions':rows,'categoryTargets':targets,'activityGuards':d['form_context_guards'],'activitySpecificSenses':[{'specific':v['specific'],'broad':v['broad']} for v in d['specific_senses']],'activityContainments':[{'outer':v['outer_activity'],'inner':v['inner_activity'],'mode':v['mode']} for v in d['containment_intersections']],'fulfillmentLexicon':{k:v for k,v in d['fulfillment_lexicon'].items() if isinstance(v,list)},'caseFoldExtras':extras}
 types={'activityDefinitions':'readonly ActivityDefinition[]','categoryTargets':'readonly CategoryTarget[]','activityGuards':'readonly ActivityGuard[]','activitySpecificSenses':'readonly {specific:string;broad:string}[]','activityContainments':'readonly {outer:string;inner:string;mode:string}[]','fulfillmentLexicon':'Readonly<Record<string,readonly string[]>>','caseFoldExtras':'Readonly<Record<string,string>>'}
 text='// Generated by scripts/compile-activity-runtime.py. Finite forms are candidates, not bank observations.\n'
 text+="export const activityDataSha256='"+hashlib.sha256(raw).hexdigest()+"';\n"
 text+="export type ActivityDefinition={id:string;domain:string;key:string;mode:'SEMANTIC_TARGET'|'CONTEXT_ROUTER';forms:readonly string[]};\nexport type CategoryTarget={key:string;path:readonly string[];labels:readonly string[]};\nexport type ActivityGuard={id:string;activity_refs:readonly string[];forms:readonly string[];condition:string};\n"
 for k,v in values.items():text+='export const '+k+':'+types[k]+'='+json.dumps(v,ensure_ascii=False,separators=(',',':'))+';\n'
 return text.encode()
def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--check',action='store_true');a=p.parse_args();raw=build()
 if a.check:
  if not OUT.is_file() or OUT.read_bytes()!=raw:raise ValueError('ACT runtime data drift: run compiler')
 else:OUT.parent.mkdir(parents=True,exist_ok=True);OUT.write_bytes(raw)
 print(json.dumps({'status':'PASS_FINITE_ACT_DATA','activities':194,'forms':4282,'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest(),'runtime_accuracy_claim':False,'paid_posts':0}))
if __name__=='__main__':main()
